import{_ as e,o,c as a,a2 as s}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"Choosing an Extension","description":"","frontmatter":{},"headers":[],"relativePath":"guides/extensions.md","filePath":"guides/extensions.md","lastUpdated":1790952322000}'),n={name:"guides/extensions.md"};function i(r,t,d,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="choosing-an-extension" tabindex="-1">Choosing an Extension <a class="header-anchor" href="#choosing-an-extension" aria-label="Permalink to &quot;Choosing an Extension&quot;">​</a></h1><p>Memoh has five ways to extend what a bot can do. They sound alike until you put them side by side — so here they are, side by side.</p><table tabindex="0"><thead><tr><th>Extension</th><th>What it is</th><th>Where it lives / how it fires</th><th>Best for</th></tr></thead><tbody><tr><td><a href="./skills.html">Skills</a></td><td><code>SKILL.md</code> prompt modules that change how the bot behaves</td><td>In the bot workspace under <code>/data/skills/</code>, managed on the <strong>Skills</strong> tab; invoked in conversation</td><td>Routines and working styles you would otherwise retype every time</td></tr><tr><td><a href="./hooks.html">Hooks</a></td><td>Event rules in <code>hooks.json</code> that run commands or tools</td><td>In <code>/data/.memoh/hooks.json</code>, edited on the <strong>Hooks</strong> tab; fires on lifecycle events such as <code>PreToolUse</code> or <code>TurnEnd</code></td><td>Checks and side effects at fixed points, with no chat involved</td></tr><tr><td><a href="./mcp.html">MCP</a></td><td>Connections to external MCP tool servers</td><td>Configured per bot on the <strong>MCP</strong> tab, as a Stdio or Remote connection; discovered tools are used during conversation</td><td>Attaching a tool that already ships an MCP server</td></tr><tr><td><a href="./connectors.html">Connectors</a></td><td>OAuth or API-key bindings to services such as GitHub or Notion</td><td>Connected from the Supermarket&#39;s <strong>Connectors</strong> tab, managed on the bot&#39;s <strong>Connectors</strong> tab; the service&#39;s tools appear in conversation</td><td>Letting the bot act on your account of a hosted service</td></tr><tr><td><a href="./supermarket.html">Supermarket</a></td><td>Memoh&#39;s built-in catalog: one-click install of packaged apps — skills plus their dependencies and connectors</td><td>Under <strong>Settings</strong>; what you install lands in the target bot&#39;s own tabs</td><td>Getting a ready-made capability without assembling the parts</td></tr></tbody></table><p>However the capability arrives, it converges in the same place: connector and MCP tools appear alongside the bot&#39;s workspace tools in conversation, and installed skills show up on the bot&#39;s <strong>Skills</strong> tab like hand-written ones.</p><h2 id="which-should-i-use" tabindex="-1">Which should I use? <a class="header-anchor" href="#which-should-i-use" aria-label="Permalink to &quot;Which should I use?&quot;">​</a></h2><ul><li>Change how the bot does its work → a <a href="./skills.html">Skill</a>.</li><li>Do something automatically at a fixed event → a <a href="./hooks.html">Hook</a>.</li><li>Attach a tool that has an MCP server → <a href="./mcp.html">MCP</a>.</li><li>Let the bot use your GitHub or Notion account → a <a href="./connectors.html">Connector</a>.</li><li>Install a ready-made package in one click → <a href="./supermarket.html">Supermarket</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">They combine</p><p>These are not competing options. An installed Supermarket app may bring skills and connectors together, and a hook can guard tools that arrived through MCP. Pick by the question above, not one per bot.</p></div><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p>Each option has a full page with the details this table compresses:</p><ul><li><a href="./skills.html">Skills</a> — writing <code>SKILL.md</code>, skill states, and adopting discovered skills.</li><li><a href="./hooks.html">Hooks</a> — the event catalog, the config schema, and testing a rule.</li><li><a href="./mcp.html">MCP</a> — Stdio and Remote connections, OAuth, and tool discovery.</li><li><a href="./connectors.html">Connectors</a> — connection statuses, reauthorization, and tool namespaces.</li><li><a href="./supermarket.html">Supermarket</a> — browsing the catalog and installing to a bot.</li></ul><p>If you are unsure, browse the Supermarket first — an installed package shows what a finished setup looks like before you build your own.</p>',11)])])}const m=e(n,[["render",i]]);export{p as __pageData,m as default};
